function validate([s, t, nums]) {
  if (typeof s !== 'string' || s.length < 1 || s.length > 100000) return 's needs 1 to 10^5 letters.';
  if (!/^[a-z]+$/.test(s)) return 's may contain only lowercase letters.';
  if (!Number.isInteger(t) || t < 1 || t > 1000000000) return 't must be a whole number from 1 to 10^9.';
  if (!Array.isArray(nums) || nums.length !== 26) return 'nums needs exactly 26 entries, one per letter.';
  if (nums.some(v => !Number.isInteger(v) || v < 1 || v > 25)) return 'Each nums[i] is a whole number from 1 to 25.';
  return null;
}

