function lengthAfterTransformations(s, t, nums) {
  const MOD = 1000000007n;

  function multiply(a, b) {
    return a.map(row => {
      const out = new Array(26).fill(0n);
      for (let k = 0; k < 26; k++) {
        for (let j = 0; j < 26; j++) {
          out[j] += row[k] * b[k][j];
        }
      }
      return out.map(value => value % MOD);
    });
  }

  let transition = Array.from({ length: 26 }, () => new Array(26).fill(0n));
  for (let letter = 0; letter < 26; letter++) {
    for (let k = 1; k <= nums[letter]; k++) {
      transition[letter][(letter + k) % 26] = 1n;
    }
  }
  let counts = [new Array(26).fill(0n)];
  for (const ch of s) {
    counts[0][ch.charCodeAt(0) - 97] += 1n;
  }
  for (let rounds = t; rounds > 0; rounds = Math.floor(rounds / 2)) {
    if (rounds % 2 === 1) {
      counts = multiply(counts, transition);
    }
    transition = multiply(transition, transition);
  }
  const total = counts[0].reduce((sum, value) => sum + value, 0n);
  return Number(total % MOD);
}

