function lengthAfterTransformations(s, t, nums) {
  // Simulate the 26 letter counts one round at a time; only additions, so plain numbers stay exact.
  const MOD = 1000000007;
  let counts = new Array(26).fill(0);
  for (const ch of s) counts[ch.charCodeAt(0) - 97]++;
  for (let round = 0; round < t; round++) {
    const next = new Array(26).fill(0);
    for (let from = 0; from < 26; from++) {
      for (let k = 1; k <= nums[from]; k++) {
        const to = (from + k) % 26;
        next[to] = (next[to] + counts[from]) % MOD;
      }
    }
    counts = next;
  }
  return counts.reduce((sum, value) => (sum + value) % MOD, 0);
}

