function generate(rand, size) {
  const pick = n => Math.floor(rand() * n);
  const large = size === 'large';
  const length = large ? 10000 : 1 + pick(8);
  // Letters come from a window of 1, 3 or 26 letters starting anywhere, so repeats and wrap-arounds both occur.
  const offset = pick(26);
  const span = [1, 3, 26][pick(3)];
  let s = '';
  for (let i = 0; i < length; i++) s += String.fromCharCode(97 + (offset + pick(span)) % 26);
  const style = pick(5);
  const nums = Array.from({ length: 26 }, () => {
    if (style === 0) return 1;
    if (style === 1) return 25;
    if (style === 2) return 1 + pick(3);
    return 1 + pick(25);
  });
  const t = large ? (rand() < 0.3 ? 1000000000 : 1 + pick(1000000000)) : 1 + pick(rand() < 0.7 ? 12 : 200);
  return [s, t, nums];
}
